<template>
  <div class="layout-px-spacing">
    <ul class="navbar-nav flex-row mt-2">
      <li>
        <div class="page-header">
          <nav class="breadcrumb-one" aria-label="breadcrumb">
            <ol class="breadcrumb">
              <li class="breadcrumb-item"><a href="javascript:;">ASSET</a></li>
              <li class="breadcrumb-item active" aria-current="page">
                 READINGS
              </li>
            </ol>
          </nav>
        </div>
      </li>
    </ul>

    <div class="row layout-top-spacing">
        <div class="d-flex">
            <div class="ms-auto">
                <button class="btn btn-primary m-2"
                data-bs-toggle="modal" data-bs-target="#register"
                @click="getRawData()"
                >
                <i class="bi bi-plus-square"></i>
                </button>
            </div>
        </div>
      <div v-if="loading" v-html="tableShimmer()"></div>
      <div 
      v-else
      class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
        <div class="panel p-0">
          <div class="custom-table table3">
            <v-client-table :data="readings" :columns="columns" >
              <template #actions="props">
                              
                                <a href="javascript:;" class="edit me-3 " @click="openEditModal(props.row); getReadingAdjustment()" data-bs-toggle="modal" :data-bs-target="'#edit-modal'">
                                   <i class="bi bi-eye text-primary text-center  fs-4"></i>
                                </a>
                               
                            </template>
            </v-client-table>
          </div>
        </div>
      </div>
    </div>
    </div>

    <!-- manual registration modla starts -->
     
                 <div class="modal fade mymodal" id="register" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="staticBackdropLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content" >
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="staticBackdropLabel">ASSET READING</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close-register" ></button>
      </div>
      <form @submit.prevent="saveReading()">
<div class="modal-body" >
      <div class="row layout-top-spacing">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                      <div class="row mb-3">
                        <div class="col-md-6">
                          <label class="form-label">Asset List</label>
   <multiselect 
                    v-model="formData.asset"
                    :options= "assets"
                    label = "name"
                    placeholder="Select Item"
                    :required = "true"
                    :searchable = "true"        
                    multple="false"
                    ></multiselect>                        </div>

                           <div class="col-md-6">
                          <label class="form-label">Reading Location</label>
   <multiselect 
                    v-model="formData.location"
                    :options= "locations"
                    label = "name"
                    placeholder="Select Item"
                    :required = "true"
                    :searchable = "true"        
                    multple="false"
                    ></multiselect>         
                </div>

                                           <div class="col-md-6">
                          <label class="form-label">Odometer Reading</label>
<input type="number" step="any" class="form-control " :style="formData?.asset?.current_odometer_reading < formData.reading ? `border: 2px solid greenyellow;` :`border: 2px solid red;`" v-model="formData.reading" placeholder="Reading Value">  
<sub>Current Reading : {{ formData?.asset?.current_odometer_reading }}</sub>      
                </div>
                                                      <div class="col-md-6">
                          <label class="form-label">Unit Reading</label>
<multiselect 
                v-model="unit"
                :options= "unitList"
                placeholder="select unit"
                label="short_name"
                :searchable = "true"        
                multple="false"
                :required="true"
                :allow-empty="false"
            ></multiselect>     
                </div>


                      </div>
                    </div>
                </div>
            </div>
        </div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-danger" data-bs-dismiss="modal">Close</button>
        <button type="submit" class="btn btn-success " :disabled="sending">
            <span v-if="sending" v-html="loadingSpinner()"></span>
            <span v-else>Save</span>
        </button>

      </div>
      </form>


    </div>
  </div>

</div>
     <!-- manual registration modal ends -->

     <div class="modal fade mymodal" id="edit-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="editConversionFactorModalLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content">
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="editConversionFactorModalLabel">Update {{ asset_reading.asset }} Reading</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" @click="resetForm(); "></button>
      </div>
      <form @submit.prevent="updateAssetReading()">
        <div class="modal-body">
           <h5>Basic Information</h5>
            <div  class="row my-3">
                                         <div class="col-md-6">
                          <label class="form-label">Odometer Reading</label>
<input type="number" step="any" class="form-control "  v-model="formData.reading" placeholder="Reading Value">  
<sub>Current Reading : {{ formData?.asset?.current_odometer_reading }}</sub>      
                </div>
                        <div class="col-md-6">
                           <label class="form-label small">Asset List</label>
                 <multiselect 
                    v-model="formData.asset"
                    :options= "assets"
                    label = "name"
                    placeholder="Select Item"
                    :required = "true"
                    :searchable = "true"        
                    multple="false"
                    v-if="!loading_data "
                    ></multiselect>  
                   </div>

                    <div class="col-md-12 mt-3">
                <label class="form-label">Adjustment Reason</label>
                <input type="text" class="form-control" placeholder="Any Reason" v-model="formData.description" required >
            </div>

              
                  
                      </div>
                      <h5>Adjustment History</h5>
        <div v-if="loading_adjustments" v-html="tableShimmer()"></div>
  <div v-else class="panel p-0">
    <div class="custom-table table3">
      <v-client-table :data="adjustments" :columns="adjustmentColumns" />
    </div>
  </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" data-bs-dismiss="modal" @click="resetForm()" id="close_editing">Close</button>
          <button type="submit" class="btn btn-primary" :disabled="submitting">
            <span v-if="submitting" class="spinner-border spinner-border-sm text-white me-2" role="status"></span>
            Submit
          </button>
        </div>
      </form>
    </div>
  </div>
</div>


</template>

<script setup>
import { ref, onMounted ,watch, inject } from 'vue'
import axios from 'axios'
import Multiselect from '@suadelabs/vue3-multiselect';
import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';

const axiosInstance = axios.create({
  baseURL: process.env.VUE_APP_API_BASE_URL
})
  
const user_id = JSON.parse(localStorage.getItem("user")).id
const loading = ref(false)
const formatDate = inject('formatDate')
const columns = ref(['Sno','asset', 'reading','unit', 'source','read_by','time','location','actions']);
const readings = ref([])
const tableShimmer = inject('tableShimmer')
const getReadings = async (showLoader = true) => {
    if (showLoader) loading.value = true;
    try{
const res = await axiosInstance.get('/readings')
  readings.value = res.data.map((item,index)=>({
    ...item,
   Sno : index + 1,
   asset :item?.subject?.asset?.name + ' - ' +item?.subject?.asset?.type_name ,
   asset_id:item.subject.asset.id,
   reading : item?.reading_value,
   unit:item?.unit?.short_name,
   source : item?.reading_source,
   read_by : item?.handler,
   time : formatDate(item?.reading_time),
   location :item?.location?.name
  }))
    }finally{
     if (showLoader) loading.value = false;
    }
  
}

const formData = ref({
    asset : '',
    location : '',
    reading : '',
    previous_value: '',
    description: ''
})
const asset = ref('')
const unit = ref('');
const rawData = ref([])
const assets = ref([])
const locations = ref([])
const loading_data = ref(false);
const getRawData = async () => {
  loading_data.value = true;

  try {
    const response = await axiosInstance.get('/readings-raw-data');
    rawData.value = response.data;
    assets.value = rawData.value.assets.map((item, index) => ({
      ...item,
      name: item?.name + (item?.type_name ? ' - ' + item.type_name : ''),
    }));
    locations.value = rawData.value.locations;
  } catch (error) {
    showError(error.message)
    console.error(error);
  } finally {
    loading_data.value = false;
  }
};

const showError = inject('showError')
const loadingSpinner = inject('loadingSpinner')
const showMessage = inject('showMessage')
const sending = ref(false)
const saveReading = async()=>{
    sending.value = true
const now = new Date().toISOString();

const payload = {
    handler: JSON.parse(localStorage.getItem("user")).name,
    company_id: 6,
    reading_value: formData.value.reading,
    reading_source: 'MANUAL',
    location_id: formData.value.location.id,
    registrar_id: JSON.parse(localStorage.getItem("user")).id,
    asset_id: formData.value.asset.id,
    unit_id: unit.value.id,
}
    try{
    const response = await axiosInstance.post('readings',payload)
    showMessage('reading Saved')
    document.getElementById('close-register').click()
    getReadings(false)
    }catch(error){
        console.log(error)
        showError(error.message)
    }finally{
        sending.value = false
    }

}

    const unitList = ref([]);
    const getUnits = async () => {
        try {
            const response = await axiosInstance.get('/units');
            unitList.value = response.data;
        } catch (error) {
            showError(error.message);
            console.log(error)
        }
    };


    const asset_reading = ref('');
    const openEditModal = (row) => {
      formData.value.previous_value = row.reading;
    asset_reading.value = row;
   formData.value.reading = row.reading;
    unit.value = unitList.value.find(a => a.id === row.unit_id) || null;
    formData.value.asset = assets.value.find(a => a.id === row.asset_id) || null;
      formData.value.location = locations.value.find(loc => loc.name === row.location) || null;



    };
    
  const resetForm = () => {
    formData.value.location = '';
    formData.value.asset = '';
       unit.value = '';
        formData.value.reading = '';

    }

const submitting = ref(false);
            const updateAssetReading = async () => {
        submitting.value = true;

        const payload = {
          reading_id :asset_reading.value.id,
          previous_value : formData.value.previous_value,
           reading_value: formData.value.reading,
          adjusted_by:user_id,
          asset_id: formData.value.asset.id,
          reason: formData.value.description
  
        };

        try {
            const response = await axiosInstance.put(`/readings/${asset_reading.value.id}`, payload);
           getReadings (false);
            showMessage('updated successfully!');
            document.getElementById('close_editing').click();
            resetForm();
        } catch (error) {
            showError(error.message);
            console.log(error)
        } finally {
            submitting.value = false;
        }
    };



const loading_adjustments = ref(false);
    const adjustments = ref([]);
    const adjustmentColumns = ref(['Sno','previous_value','adjusted_value','adjustment_reason', 'adjustment_time','read_by','adjusted_by',]);
const getReadingAdjustment = async () => {
  loading_adjustments.value = true
  try {
    const response = await axiosInstance.get(`/reading-adjustments?reading_id=${asset_reading.value.id}`);
    adjustments.value = response.data.map((item, index) => ({
      ...item,
      Sno: index + 1,
      adjusted_value: item?.corrected_value,
      adjustment_reason: item?.reason,
      adjustment_time: formatDate(item?.created_at),
      read_by:item.reader.name,
      adjusted_by:item.issuer.name
    }));
  } catch (error) {
    showError(error.message);
  }finally{
    loading_adjustments.value = false
  }
};


onMounted(() => {
  getReadings();
  getUnits();
  getRawData();
})
</script>